// Three recursive traversal shapes — only visit(n) moves

function preorder(n) {
  if (!n) return;
  visit(n);                 // root FIRST
  preorder(n.left);
  preorder(n.right);
}

function inorder(n) {
  if (!n) return;
  inorder(n.left);
  visit(n);                 // root MIDDLE
  inorder(n.right);
}

function postorder(n) {
  if (!n) return;
  postorder(n.left);
  postorder(n.right);
  visit(n);                 // root LAST
}

// Classic uses:
//   preorder  -> serialize a tree, clone, print structure top-down
//   inorder   -> BST scan in SORTED order
//   postorder -> bottom-up aggregation (subtree sum, height, safe delete)

