function inorder(n, out) {
  if (!n) return;
  inorder(n.___, out);
  out.push(n.val);
  inorder(n.___, out);
}
const root = { val: 2, left: { val: 1, left: null, right: null }, right: { val: 3, left: null, right: null } };
const out = [];
inorder(root, out);
console.log(JSON.stringify(out));

function preorder(n, out) {
  if (!n) return;
  out.___(n.val);
  preorder(n.left, out);
  preorder(n.right, out);
}
function postorder(n, out) {
  if (!n) return;
  postorder(n.left, out);
  postorder(n.right, out);
  out.___(n.val);
}
const root = { val: 2, left: { val: 1, left: null, right: null }, right: { val: 3, left: null, right: null } };
const pre = [], post = [];
preorder(root, pre);
postorder(root, post);
console.log(JSON.stringify(pre));
console.log(JSON.stringify(post));

